# target TR 4x4
for r in range(4,8):
    for c in range(19,23): G[r][c]=2
# BL and BR 2x2
for r in (19,20):
    for c in (5,6): G[r][c]=2
    for c in (20,21): G[r][c]=2
# template non-core colored cells, represented offsets from top-left core (5,5)
patches=[]
for c in (5,6): patches.append((-1,c-5,6))
patches.append((0,-1,5))
for c in (3,4): patches.append((1,c-5,3))
for r in (7,8):
    for c in (5,6): patches.append((r-5,c-5,1))
# apply scaled/reflected in each other quadrant
for ar,ac,n,flip_r,flip_c in [(4,19,4,False,True),(19,5,2,True,False),(19,20,2,True,True)]:
    k=n//2
    for dr,dc,color in patches:
        rr = n-(dr+1)*k if flip_r else dr*k
        cc = n-(dc+1)*k if flip_c else dc*k
        for i in range(k):
            for j in range(k):
                y,x=ar+rr+i,ac+cc+j
                if 0<=y<27 and 0<=x<27:
                    # Patterns should only fall in active quadrants and not collide with core
                    G[y][x]=color
print('\n'.join(' '.join(map(str,row)) for row in G))

